// All devices, commands, addresses and files below are a browser-local teaching model.
// No command is executed and no network traffic leaves the browser.
export const desktopConnections=[
 {id:'pcPower',label:'PC power',type:'power',from:'Power strip',to:'PC · AC IN',detail:'The PSU converts power to the DC voltages needed by PC components.'},
 {id:'monitorPower',label:'Monitor power',type:'power',from:'Power strip',to:'Monitor · DC IN',detail:'Video signals and power are separate. HDMI alone does not power this monitor.'},
 {id:'display',label:'Video cable',type:'video',from:'PC · HDMI OUT',to:'Monitor · HDMI IN',detail:'It carries the GPU’s video output to the monitor. This lab uses the dedicated graphics card output.'},
 {id:'keyboard',label:'Keyboard',type:'usb',from:'Keyboard · USB',to:'PC · USB port',detail:'Keystrokes travel as USB HID reports. The PC interprets them and passes them to applications.'},
 {id:'mouse',label:'Mouse',type:'usb',from:'Mouse · USB',to:'PC · USB port',detail:'Movement and button states travel over USB. The pointer and click results appear on the monitor.'},
 {id:'ethernet',label:'Network',type:'network',from:'PC · RJ45',to:'Router · LAN 1',detail:'Communication needs an Ethernet link and IP settings. The lab router assigns 192.168.10.20 using DHCP.'}
];
export const serverConnections=[
 {id:'mains',label:'Facility power → UPS',type:'power',from:'Facility power',to:'UPS input',detail:'The UPS briefly maintains power during an outage, giving equipment time to shut down safely. This lab compresses battery runtime to 15 seconds.'},
 {id:'pdu',label:'UPS → PDU',type:'power',from:'UPS output',to:'Rack PDU',detail:'The PDU distributes power to the server, switch, and router. Both PSUs share this UPS and PDU, so the complete power path is not redundant.'},
 {id:'psuA',label:'PSU A',type:'power',from:'PDU · 01',to:'Server power A',detail:'The first server power supply module. This model can carry the full server load on one PSU.'},
 {id:'psuB',label:'PSU B',type:'power',from:'PDU · 02',to:'Server power B',detail:'If either A or B is disconnected, the other carries the load. Independent power circuits require a separate design.'},
 {id:'nic',label:'Server → switch',type:'network',from:'Server · NIC 1',to:'Switch · 01',detail:'It carries frames between the admin PC and server on the same subnet. Set the server IP in the installer.'},
 {id:'uplink',label:'Switch → router',type:'network',from:'Switch · 24',to:'Router · LAN',detail:'The default path to other networks. PC-to-server traffic within the same VLAN does not pass through the router.'},
 {id:'client',label:'Admin PC → switch',type:'network',from:'Admin PC · RJ45',to:'Switch · 02',detail:'The admin PC at 10.20.0.100 accesses the server over SSH or HTTP. This lab uses a single VLAN.'},
 {id:'console',label:'Local console',type:'usb',from:'KVM · USB + video',to:'Server · console port',detail:'A directly connected display and keyboard let you manage the server even when networking is down.'}
];
export const deskSteps=[
 ['Connect PC power','Where the power starts','pcPower','Connect the PSU’s rear AC input to the power strip. The computer is still switched off.','Connect power'],
 ['Connect monitor power','A display needs power too','monitorPower','Connect the monitor’s power adapter. It stays in standby until it receives a video signal.','Connect monitor power'],
 ['Connect the video cable','A path for pixels','display','Connect the PC’s HDMI output to the monitor input. Notice that power and video use separate cables.','Connect HDMI'],
 ['Connect the keyboard','Your first keystroke','keyboard','Plug the keyboard’s USB cable into the PC. Input signals pass through the operating system to applications.','Connect the keyboard'],
 ['Connect the mouse','Turn movement into input','mouse','Connect the mouse to a USB port. Physical movement becomes pointer movement on screen.','Connect the mouse'],
 ['Connect the network','Talk to another device','ethernet','Use an RJ45 cable to connect to the router’s LAN port. DHCP automatically assigns an address on this small lab network.','Connect LAN cable'],
 ['Power on','POST → operating system','boot','Press the power button to run hardware checks and boot the simulated operating system. Both monitor power and HDMI must be connected to see the screen.','Power on PC'],
 ['Keyboard input and output','Input → processing → output','input','Send HELLO, PC! and watch the path light up as USB input enters the PC and text appears on screen. You can also send your own message below.','Send sample keystrokes'],
 ['Mouse input and output','A click changes the screen','pointer','Use the virtual mouse to click an on-screen button. Once the click is processed, the monitor shows a confirmation.','Click with the mouse'],
 ['Test networking · Unplug a cable','What happens if you disconnect?','ping','Exchange ICMP requests and replies with the gateway. Then disconnect HDMI, USB, and LAN one at a time in the panel below and compare what stops working.','Ping test']
].map(([name,tag,action,body,button])=>({name,tag,action,body,button}));
export const serverSteps=[
 ['Mount the server','01 / HARDWARE','rack','Secure the rails and slide the server into the rack. Place heavy equipment lower down and leave space for front-to-back airflow. This model uses a 2U server in a 12U rack.','Mount server'],
 ['Install storage','02 / HARDWARE','disks','Insert two 480 GB SSDs into the drive bays. During installation, choose a single disk or a conceptual RAID 1 mirror.','Install two SSDs'],
 ['Connect the power path','03 / POWER','power','Connect facility power → UPS → PDU → server PSU A/B. The switch and router also receive power from the PDU.','Connect power cables'],
 ['Wire the network','04 / NETWORK','network','Connect the server and admin PC to the same switch, then connect the router uplink. The LAN is 10.20.0.0/24 and the router is 10.20.0.1.','Connect network cables'],
 ['Connect a console','05 / CONSOLE','console','Connect the KVM display and keyboard directly to the server. The local console works before OS installation and during network faults.','Connect KVM'],
 ['Prepare installation media','06 / BOOT MEDIA','media','Put the Ubuntu Server 24.04 LTS ISO on a virtual USB drive. On real hardware, verify the official ISO and use bootable USB or BMC virtual media.','Connect virtual USB'],
 ['Power on · Boot with UEFI','07 / BOOT','boot','Power on the server and check CPU, RAM, and SSD detection during POST. Select the installation USB in the UEFI boot menu to enter the Linux installer.','Boot USB from UEFI'],
 ['Install Linux','08 / OPERATING SYSTEM','install','Choose language and keyboard, IP settings, storage, and an administrator account with SSH, then install. These Ubuntu Server learning screens use no real disks.','Start Linux installation'],
 ['Remove media · Reboot','09 / FIRST BOOT','reboot','Remove the installation USB and reboot from local disk. The kernel and services start, preparing the new Linux server for login.','Remove USB and reboot'],
 ['Connect over SSH','10 / REMOTE ACCESS','ssh','Connect from the admin PC over SSH. Both devices share a subnet, so traffic follows PC → switch → server. The lab simulates public-key authentication.','SSH from admin PC'],
 ['Install a web service','11 / SERVICE','service','Refresh package information and install nginx. The web server listens for HTTP requests on TCP port 80. You can also enter commands directly in the practice console.','Install and start nginx'],
 ['Configure the firewall','12 / FIREWALL','firewall','Allow port 22 for SSH and port 80 for HTTP before enabling UFW. This lab covers access within the office LAN, without exposing the server to the internet.','Allow SSH + HTTP, enable UFW'],
 ['Check request and response','13 / VERIFY','request','The admin PC resolves office.example using DNS and sends an HTTP request. A returned page shows that the network, operating system, and service are working together.','Request the web page'],
 ['Back up · Try a fault','14 / OPERATE','backup','Create a separate backup of the web content. RAID handles disk failure but does not replace backups for deleted or corrupted data. Now try power, LAN, and DNS faults.','Create practice backup']
].map(([name,tag,action,body,button])=>({name,tag,action,body,button}));
export function createDesktop(){return {connections:Object.fromEntries(desktopConnections.map(c=>[c.id,false])),on:false,text:'',clicks:0,step:0,completed:0,events:[],lastFlow:null};}
export function createServer(){return {connections:Object.fromEntries(serverConnections.map(c=>[c.id,false])),rack:false,disks:false,media:false,on:false,booted:false,installed:false,installing:false,needsReboot:false,step:0,completed:0,battery:15,batteryActive:false,dnsFault:false,session:'local',ssh:false,nginx:false,nginxInstalled:false,firewall:false,allowSSH:false,allowHTTP:false,backup:false,webContent:'Hello from PC LAB',network:{mode:'static',ip:'10.20.0.10',prefix:24,gateway:'10.20.0.1',dns:'10.20.0.1'},host:'office-web',user:'admin',storage:'mirror',language:'English',keyboard:'us',sshRequested:true,events:[],lastFlow:null};}
export function desktopStatus(s){const c=s.connections;const running=s.on&&c.pcPower;return {running,screen:running&&c.monitorPower&&c.display,keyboard:running&&c.keyboard,mouse:running&&c.mouse,network:running&&c.ethernet,ip:running&&c.ethernet?'192.168.10.20':'—'};}
export function serverStatus(s){const c=s.connections;const ups=c.mains||s.batteryActive&&s.battery>0;const distribution=ups&&c.pdu;const power=distribution&&(c.psuA||c.psuB);const running=power&&s.on&&s.booted&&s.installed&&!s.needsReboot;const serverLink=running&&distribution&&c.nic;const clientLink=distribution&&c.client;const lan=serverLink&&clientLink;const gateway=serverLink&&c.uplink;const clientGateway=clientLink&&c.uplink;const dns=gateway&&!s.dnsFault&&s.network.dns==='10.20.0.1';const clientDNS=clientGateway&&!s.dnsFault;return {power,distribution,running,lan,gateway,clientGateway,dns,clientDNS,local:running&&c.console,ssh:lan&&s.ssh&&(!s.firewall||s.allowSSH),http:lan&&s.nginx&&(!s.firewall||s.allowHTTP),redundant:power&&c.psuA&&c.psuB};}
export function event(s,message){s.events.unshift(message);s.events=s.events.slice(0,7);}
export function reconcileServer(s){const q=serverStatus(s);if(!q.power){if(s.on)event(s,'Power lost: the server has stopped. Restore the connection, then power it on again.');s.on=false;s.booted=false;if(s.installing){s.installing=false;s.installed=false;s.needsReboot=false;event(s,'Installation interrupted: restart the virtual disk installation from the beginning.');}}if(s.session==='remote'&&!q.ssh){s.session='client';event(s,'SSH session ended: check power, LAN, and the SSH firewall rule.');}}
export function toggleConnection(kind,s,id){if(!(id in s.connections))return;s.connections[id]=!s.connections[id];event(s,`${id} ${s.connections[id]?'Connected':'Disconnected'}`);if(kind==='desktop'&&!s.connections.pcPower)s.on=false;if(kind==='server'){if(id==='mains'){if(s.connections.mains){s.battery=15;s.batteryActive=false;}else{s.batteryActive=s.battery>0;}}reconcileServer(s);}}
export function validateConfig(c){const ipv4=v=>/^\d{1,3}(\.\d{1,3}){3}$/.test(v)&&v.split('.').every(n=>Number(n)<=255);if(!/^[a-z][a-z0-9-]{0,30}$/.test(c.host))return 'Hostname must start with a lowercase letter and use lowercase letters, numbers, or hyphens (31 characters maximum).';if(!/^[a-z][a-z0-9_-]{0,30}$/.test(c.user))return 'Username must start with a lowercase letter and use lowercase letters, numbers, underscores, or hyphens.';if(c.network.mode==='static'){if(!ipv4(c.network.ip)||!c.network.ip.startsWith('10.20.0.'))return 'An IPv4 address in this lab LAN must be in the range 10.20.0.2–254.';const end=Number(c.network.ip.split('.')[3]);if(end<2||end>254||end===100)return 'Do not use the gateway (.1), admin PC (.100), network (.0), or broadcast (.255) address.';}if(c.network.gateway!=='10.20.0.1')return 'The lab router’s gateway address is 10.20.0.1.';if(!ipv4(c.network.dns))return 'Check the DNS server’s IPv4 address format.';return '';}
export function desktopAction(s,action,value){const q=desktopStatus(s);if(action in s.connections){s.connections[action]=true;return `${action} connected`;}if(action==='boot'){if(!s.connections.pcPower)return {error:'Connect the PC power cable first.'};s.on=true;event(s,'POST OK → Simulated operating system booted');return 'Boot complete';}if(action==='input'){if(!q.keyboard)return {error:'Power on the PC and connect the keyboard.'};s.text=value||'HELLO, PC!';s.lastFlow='input';return q.screen?'USB input → CPU processing → HDMI output':'Keystrokes were processed, but display output is disconnected.';}if(action==='pointer'){if(!q.mouse)return {error:'Power on the PC and connect the mouse.'};s.clicks++;s.lastFlow='pointer';return q.screen?'Mouse click processed and display updated.':'The click was processed, but display output is disconnected.';}if(action==='ping'){if(!q.network)return {error:'Check PC power and the LAN cable.'};s.lastFlow='ping';return '192.168.10.1 replied · 4/4 received · Simulated RTT 1 ms';}}
export function serverAction(s,action){const c=s.connections,q=serverStatus(s);const fail=error=>({error});
 if(action==='rack'){s.rack=true;return 'Server secured to rack rails';}
 if(action==='disks'){if(!s.rack)return fail('Mount the server in the rack first.');s.disks=true;return 'Detected 2 × 480 GB SSD';}
 if(action==='power'){if(!s.rack)return fail('Mount the server in the rack first.');for(const id of ['mains','pdu','psuA','psuB'])c[id]=true;s.battery=15;s.batteryActive=false;return 'UPS · PDU · Dual PSU power path connected';}
 if(action==='network'){for(const id of ['nic','uplink','client'])c[id]=true;return 'Server · Switch · Router · Admin PC links connected';}
 if(action==='console'){c.console=true;return 'KVM console connected';}
 if(action==='media'){s.media=true;return 'Ubuntu Server 24.04 LTS virtual USB ready';}
 if(action==='boot'){if(!q.power)return fail('At least one complete UPS → PDU → PSU power path is required.');if(!s.disks)return fail('Install the SSDs first.');if(!c.console)return fail('Connect a KVM console to view the boot screen.');if(!s.media&&!s.installed)return fail('Connect the installation USB.');s.on=true;s.booted=true;return s.installed&&!s.media?'Linux boot complete':'POST OK · UEFI USB → Ubuntu installer ready';}
 if(action==='install'){if(!q.power||!s.on||!s.booted||!s.media||!c.console)return fail('Connect power, KVM, and the installation USB, then boot the USB through UEFI first.');return {installer:true};}
 if(action==='reboot'){if(!s.installed)return fail('Complete the Linux installation first.');if(!q.power)return fail('Restore the power path.');s.media=false;s.needsReboot=false;s.on=true;s.booted=true;return 'Installation media removed → Disk boot → Linux ready';}
 if(action==='ssh'){if(!q.ssh)return fail('Check server boot, LAN connectivity, OpenSSH installation, and port 22 access. You can install SSH in the local console with sudo apt install openssh-server.');s.session='remote';s.lastFlow='ssh';return `Public-key authentication accepted · ${s.user}@${s.host} connected`;}
 if(action==='service'){if(!q.running)return fail('Boot Linux first.');if(!q.gateway||!q.dns)return fail('Package repository access requires LAN, an uplink, and DNS.');s.nginx=true;s.nginxInstalled=true;return 'apt update → apt install nginx → nginx active (running)';}
 if(action==='firewall'){if(!q.running)return fail('Boot Linux first.');s.allowSSH=true;s.allowHTTP=true;s.firewall=true;return '22/tcp · 80/tcp allowed → UFW enabled';}
 if(action==='request'){if(!q.clientDNS)return fail('Cannot resolve office.example. Check the uplink and DNS settings, then compare with a request by IP.');if(!q.http)return fail('HTTP connection failed: check the server, LAN, nginx, and port 80 access.');s.lastFlow='http';return `DNS office.example → ${s.network.ip} · HTTP/1.1 200 OK · ${s.webContent}`;}
 if(action==='backup'){if(!q.running||!s.nginx)return fail('Set up Linux and the web service first.');s.backup=true;s.backupContent=s.webContent;return 'Web content copied to separate simulated backup storage';}
 return fail('This lab action is not supported.');
}
export function runCommand(s,raw){const cmd=raw.trim().replace(/\s+/g,' '),q=serverStatus(s);const result=(output,flow=null)=>({output,flow});
 if(cmd==='help')return result('Practice commands (never executed on your real system)\nhelp · clear · hostname · whoami · uname -a · ls · pwd\nip addr · ip route · df -h · free -h\nping 10.20.0.1 · ping office.example\nssh '+s.user+'@'+s.network.ip+' · exit\nsudo apt update · sudo apt install nginx · sudo apt install openssh-server\nsystemctl status nginx · sudo systemctl start nginx · sudo systemctl stop nginx\nsudo ufw allow OpenSSH · sudo ufw allow 80/tcp · sudo ufw enable · sudo ufw status\ncurl http://office.example · curl http://'+s.network.ip+'\nbackup · restore');
 if(cmd==='clear')return {clear:true};
 const client=s.session==='client';const resolver=client?q.clientDNS:q.dns;
 if(!client&&!q.local&&s.session!=='remote')return result('Local console unavailable: check that Linux is running and KVM is connected.');
 if(s.session==='remote'&&!q.ssh){s.session='client';return result('SSH disconnected. Returning to the admin PC.');}
 if(cmd==='exit'){s.session='client';return result('Connection closed. Returned to the admin PC.');}
 if(cmd.startsWith('ssh ')){if(!client)return result('Start the SSH connection from the Admin PC tab.');const target=cmd.slice(4);if(target!==`${s.user}@${s.network.ip}`&&target!==`${s.user}@office.example`)return result('Enter the lab server’s user@IP or user@office.example.');if(target.endsWith('office.example')&&!resolver)return result('ssh: Could not resolve hostname office.example');if(!q.ssh)return result('ssh: Connection failed. Check power, LAN, OpenSSH, and 22/tcp.');s.session='remote';return result(`Ubuntu Server 24.04 LTS (simulation)\nPublic-key authentication accepted.\nWelcome, ${s.user}.`,'ssh');}
 if(cmd==='whoami')return result(client?'operator':s.user);if(cmd==='hostname')return result(client?'admin-pc':s.host);
 if(cmd==='uname -a')return result('Linux '+(client?'admin-pc':s.host)+' 6.8.0-generic x86_64 GNU/Linux [SIMULATED]');
 if(cmd==='pwd')return result(client?'/home/operator':`/home/${s.user}`);if(cmd==='ls')return result(client?'Documents  Downloads':`README.txt  www`);
 if(cmd==='ip addr')return result(client?'eth0: '+(s.connections.client&&q.distribution?'UP':'DOWN')+'\ninet 10.20.0.100/24':`eno1: ${s.connections.nic&&q.distribution?'UP':'NO-CARRIER'}\ninet ${s.network.ip}/24\nlo: 127.0.0.1/8`);
 if(cmd==='ip route')return result(`default via 10.20.0.1 dev ${client?'eth0':'eno1'}\n10.20.0.0/24 dev ${client?'eth0':'eno1'}`);
 if(cmd==='df -h')return result(client?'Filesystem /dev/sda2 · 80G · 22G used':`Filesystem             Size   Used   Mounted on\n${s.storage==='mirror'?'/dev/md0':'/dev/sda2'}                446G   4.2G   /\n/dev/sda1              1.0G   6M     /boot/efi\nCapacity and partitions are learning approximations. Mirroring is not a backup.`);
 if(cmd==='free -h')return result('              total      used      available\nMem:           32Gi     1.2Gi         30Gi');
 if(cmd.startsWith('ping ')){const target=cmd.slice(5);if(!['10.20.0.1','office.example',s.network.ip,'10.20.0.100'].includes(target))return result('Lab targets: 10.20.0.1, office.example, '+s.network.ip+', 10.20.0.100');if(target==='office.example'&&!resolver)return result('ping: office.example: Temporary failure in name resolution');const self=(!client&&target===s.network.ip)||(client&&target==='10.20.0.100');const reach=self||(target==='10.20.0.1'?(client?q.clientGateway:q.gateway):q.lan);if(!reach)return result('Destination Host Unreachable\n4 packets transmitted, 0 received, 100% packet loss');return result(`64 bytes from ${target}: icmp_seq=1 ttl=64 time=0.8 ms\n64 bytes from ${target}: icmp_seq=2 ttl=64 time=1.0 ms\n4 packets transmitted, 4 received, 0% packet loss\n(Response times are simulated.)`,self?'loopback':target==='10.20.0.1'?'ping-gateway':target==='office.example'?'ping-dns':'ping');}
 if(cmd.startsWith('curl ')){const target=cmd.slice(5).replace(/^https?:\/\//,'').replace(/\/$/,'');if(!['office.example',s.network.ip,'localhost','127.0.0.1'].includes(target))return result('This lab’s HTTP targets are office.example or the server IP.');const local=['localhost','127.0.0.1'].includes(target);if(local&&client)return result('curl: Failed to connect to localhost port 80 (the admin PC has no web server.)');if(target==='office.example'&&!resolver)return result('curl: (6) Could not resolve host: office.example');if(local?!s.nginx:!q.http)return result('curl: (7) Failed to connect to port 80. Check LAN, nginx, and UFW.');return result(`HTTP/1.1 200 OK\nServer: nginx\n\n${s.webContent}\nHost: ${s.host}`,target==='office.example'?'http':local?'http-local':'http-ip');}
 if(client)return result('Run this command on the server. Connect over SSH or select the local console.');
 if(cmd==='sudo apt update'){if(!q.dns)return result('Temporary failure resolving archive.ubuntu.com — Check the uplink and DNS.');return result('Hit: Ubuntu noble / noble-updates / noble-security\nReading package lists... Done (simulation)');}
 if(cmd==='sudo apt install nginx'||cmd==='sudo apt install openssh-server'){if(!q.dns)return result('Package download failed: check gateway and DNS connectivity.');if(cmd.endsWith('nginx')){s.nginx=true;s.nginxInstalled=true;}else s.ssh=true;return result('Package installed. Service started. [simulation]');}
 if(cmd==='systemctl status nginx'||cmd==='sudo systemctl status nginx')return result(`nginx.service — A high performance web server\nActive: ${s.nginx?'active (running)':'inactive (dead)'}`);
 if(cmd==='sudo systemctl start nginx'){if(!s.nginxInstalled)return result('Unit nginx.service could not be found. Install it with sudo apt install nginx first.');s.nginx=true;return result('nginx started.');}if(cmd==='sudo systemctl stop nginx'){s.nginx=false;return result('nginx stopped.');}
 if(cmd==='sudo ufw allow OpenSSH'||cmd==='sudo ufw allow 22/tcp'){s.allowSSH=true;return result('Rule added: 22/tcp ALLOW');}if(cmd==='sudo ufw allow 80/tcp'){s.allowHTTP=true;return result('Rule added: 80/tcp ALLOW');}
 if(cmd==='sudo ufw enable'){s.firewall=true;reconcileServer(s);return result(s.session==='client'?'Firewall active. The missing SSH rule disconnected this session. Recover using the KVM console.':'Firewall is active.');}
 if(cmd==='sudo ufw status')return result(`Status: ${s.firewall?'active':'inactive'}\n${s.allowSSH?'22/tcp ALLOW\n':''}${s.allowHTTP?'80/tcp ALLOW':''}`);
 if(cmd==='backup'){s.backup=true;s.backupContent=s.webContent;return result('Web content copied to separate simulated backup storage.');}
 if(cmd==='restore'){if(!s.backup)return result('No backup exists. Run backup first.');s.webContent=s.backupContent;return result('Web content restored from backup. Use curl to check it.');}
 return result('Unsupported practice command. Type help to see the command list.');
}
